-- ============================================================================
-- MIGRACIÓN: Seguimiento de revisiones — datos reales iniciales
-- Fecha: 2026-09-18
--
-- Importa el histórico real de citas de biomecánica (1200 citas, 1101
-- pacientes únicos) que ya tenía la clínica en su plantilla de control de
-- revisiones, para que el módulo arranque con el trabajo ya hecho.
--
-- Nota de fidelidad de datos: la plantilla de origen mostraba una cifra de
-- pacientes distinta (939) porque sus fórmulas quedaron con el cálculo
-- desactualizado tras el último pegado de datos; esta migración parte
-- directamente de las filas de citas en bruto, que es la fuente real.
--
-- Idempotente por conflicto: reaplicar esta migración no duplica nada
-- (huella única en citas, paciente_clave+centro único en gestión).
-- ============================================================================

DO $$
DECLARE
  v_centro  UUID;
  v_usuario UUID;
BEGIN
  SELECT id INTO v_centro  FROM public.centros  WHERE nombre = 'Podología y Biomecánica Rivas';
  SELECT id INTO v_usuario FROM public.usuarios WHERE email  = 'admin@podologiarivas.com' AND activo;

  IF v_centro  IS NULL THEN RAISE EXCEPTION 'SEGUIMIENTO_DATOS: no se encuentra el centro'; END IF;
  IF v_usuario IS NULL THEN RAISE EXCEPTION 'SEGUIMIENTO_DATOS: no se encuentra el usuario administrador'; END IF;

  INSERT INTO public.seguimiento_citas
    (fecha, hora, agenda, sala, paciente_raw, paciente_clave, tratamiento, precio, estado_cita, huella, centro_id, created_by, updated_by)
  SELECT v.fecha, v.hora, v.agenda, v.sala, v.paciente_raw, v.paciente_clave, v.tratamiento, v.precio, v.estado_cita, v.huella,
         v_centro, v_usuario, v_usuario
